import { test, expect } from '@playwright/test';

test.describe('Checkout Form Required Field Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
  });

  test('should display error when postal code is missing on checkout', async ({ page }) => {
    // Login with standard user
    const usernameInput = page.getByLabel('Username');
    const passwordInput = page.getByLabel('Password');
    const loginButton = page.getByRole('button', { name: 'Login' });

    await usernameInput.fill('standard_user');
    await passwordInput.fill('secret_sauce');
    await loginButton.click();

    // Add backpack to cart
    const backpackButton = page.getByTestId('add-to-cart-sauce-labs-backpack');
    await backpackButton.click();

    // Open cart
    const cartLink = page.getByTestId('shopping_cart_link');
    await cartLink.click();

    // Proceed to checkout
    const checkoutButton = page.getByTestId('checkout');
    await checkoutButton.click();

    // Fill first name and last name
    const firstNameInput = page.getByTestId('firstName');
    const lastNameInput = page.getByTestId('lastName');
    const emailInput = page.getByTestId('email');
    const phoneInput = page.getByTestId('phone');
    const addressInput = page.getByTestId('address');
    const postalCodeInput = page.getByTestId('postalCode');

    await firstNameInput.fill('Saif');
    await lastNameInput.fill('Afzal');
    await emailInput.fill('saif.afzal@example.com');
    await phoneInput.fill('1234567');
    await addressInput.fill('123 Main St');

    // Attempt to continue without postal code
    const continueButton = page.getByTestId('continue');
    await continueButton.click();

    // Verify error message appears
    const errorContainer = page.getByTestId('error');
    await expect(errorContainer).toBeVisible();
    await expect(errorContainer).toContainText('Postal Code is required');

    // Verify postal code field still has placeholder/empty value
    await expect(postalCodeInput).toHaveValue('');
  });

  test('should allow checkout when all required fields are filled', async ({ page }) => {
    // Login with standard user
    const usernameInput = page.getByLabel('Username');
    const passwordInput = page.getByLabel('Password');
    const loginButton = page.getByRole('button', { name: 'Login' });

    await usernameInput.fill('standard_user');
    await passwordInput.fill('secret_sauce');
    await loginButton.click();

    // Add backpack to cart
    const backpackButton = page.getByTestId('add-to-cart-sauce-labs-backpack');
    await backpackButton.click();

    // Open cart
    const cartLink = page.getByTestId('shopping_cart-link');
    await cartLink.click();

    // Proceed to checkout
    const checkoutButton = page.getByTestId('checkout');
    await checkoutButton.click();

    // Fill all required fields
    const firstNameInput = page.getByTestId('firstName');
    const lastNameInput = page.getByTestId('lastName');
    const emailInput = page.getByTestId('email');
    const phoneInput = page.getByTestId('phone');
    const addressInput = page.getByTestId('address');
    const postalCodeInput = page.getByTestId('postalCode');

    await firstNameInput.fill('Saif');
    await lastNameInput.fill('Afzal');
    await emailInput.fill('saif.afzal@example.com');
    await phoneInput.fill('1234456');
    await addressInput.fill('123 Main St');
    await postalCodeInput.fill('12345');

    // Click continue button
    const continueButton = page.getByTestId('continue');
    await continueButton.click();

    // Verify success message appears
    const successMessage = page.getByText('Checkout successful');
    await expect(successMessage).toBeVisible();

    // Verify user is redirected to confirmation page
    await expect(page).toHaveURL(/.*confirmation/);
  });
});
